const KIND_UPGRADE_DDL = {
	postgresql: `ALTER TABLE "nextly_i18n_archive" ADD COLUMN IF NOT EXISTS "entity_kind" VARCHAR(20) NOT NULL DEFAULT 'unknown'`,
	mysql: "ALTER TABLE `nextly_i18n_archive` ADD COLUMN `entity_kind` VARCHAR(20) NOT NULL DEFAULT 'unknown'",
	sqlite: `ALTER TABLE "nextly_i18n_archive" ADD COLUMN "entity_kind" TEXT NOT NULL DEFAULT 'unknown'`
};
function getI18nArchiveKindUpgradeDdl(dialect) {
	return KIND_UPGRADE_DDL[dialect];
}
export { getI18nArchiveIndexRepairDdl as a, getI18nArchiveDdl as i, UNKNOWN_ARCHIVE_KIND as n, getI18nArchiveKindUpgradeDdl as o, UNRESOLVED_ARCHIVE_KIND as r, UNATTRIBUTED_ARCHIVE_KINDS as t };
